/bin/zsh -lc "python3 -B -c 'cases = 0
for k in range(1, 9):
    modulus = 1 << k
    for x in range(modulus):
        message = format(x, \"0%db\" % k)
        assert len(message) == k and set(message) <= {\"0\", \"1\"}
        for y in range(modulus):
            assert (int(message, 2) + y) % modulus == (x + y) % modulus
            cases += 1
for k in range(1, 31):
    modulus = 1 << k
    for x in (0, modulus - 1):
        message = format(x, \"0%db\" % k)
        assert len(message) == k
        for y in (0, modulus - 1):
            assert (int(message, 2) + y) % modulus == (x + y) % modulus
assert format(6, \"03b\") == \"110\"
assert (6 + 5) % (1 << 3) == 3
print(\"Exhaustive checks for k=1..8:\", cases, \"input pairs; boundary checks for k=1..30 and stated example passed.\")'"

